// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// The provided source code for Advisory contract includes the IBEP20 interface.
// However, our MockERC20 helper needs a definition to compile against.
interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

// The user must provide the concrete implementation of the Advisory contract
// for this test to compile, as it is instantiated in the setUp function.
// For example, by adding `import {Advisory} from "src/Advisory.sol";`
abstract contract Advisory {
    constructor(address token, uint256 rate, uint256 period) {}
    function owner() public view virtual returns (address);
    // Added the missing `token` function signature based on its usage in the test's setUp.
    function token() public view virtual returns (address);
    function addDistributionWallet(address[] memory users, uint[] memory amounts, uint[] memory startTimes) external virtual;
    function revokeDistributionWallet(address[] memory users) external virtual;
    function user(address) external view virtual returns (uint, uint, uint, uint);
}

contract MockERC20 is IBEP20 {
    mapping(address => uint256) public override balanceOf;
    mapping(address => mapping(address => uint256)) public override allowance;
    uint256 public override totalSupply;
    string public name = "Mock Token";
    string public symbol = "MOCK";
    uint8 public decimals = 18;

    function transfer(address recipient, uint256 amount) public virtual override returns (bool) {
        // `deal` cheatcode sets the balance, so no underflow check is needed here for the sender
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        emit Transfer(msg.sender, recipient, amount);
        return true;
    }

    function approve(address spender, uint256 amount) public virtual override returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public virtual override returns (bool) {
        allowance[sender][msg.sender] -= amount;
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        emit Transfer(sender, recipient, amount);
        return true;
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    // Removed duplicate variable declarations.
    Advisory target;
    IBEP20 distToken;
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);
    address revokedUser = address(0xdeadbeef);
    uint256 constant ALLOCATION_AMOUNT = 100 ether;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // The contract under test is at the address defined by TARGET.
        target = Advisory(TARGET);

        // Find the token used by the contract.
        address tokenAddress = target.token();
        distToken = IBEP20(tokenAddress);

        // Fund the Advisory contract with enough tokens for the allocation.
        // The test harness will have set the test contract as the owner.
        deal(tokenAddress, TARGET, ALLOCATION_AMOUNT);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Using the `target` state variable initialized in `setUp`.

        // Per the precondition, the test contract (attacker) is the owner.
        // We can optionally assert this for sanity.
        assertEq(target.owner(), attacker);

        // Step 1: Add a user to the distribution list as the owner.
        address[] memory usersToAdd = new address[](1);
        usersToAdd[0] = revokedUser;

        uint[] memory amounts = new uint[](1);
        amounts[0] = ALLOCATION_AMOUNT;

        uint[] memory startTimes = new uint[](1);
        startTimes[0] = block.timestamp + 1 days; // Start time must be in the future

        target.addDistributionWallet(usersToAdd, amounts, startTimes);

        // Verify the user was added correctly.
        (uint balanceBefore, ,,) = target.user(revokedUser);
        assertEq(balanceBefore, ALLOCATION_AMOUNT, "User balance should be set after adding");

        // Step 2: Revoke the user from the distribution list.
        address[] memory usersToRevoke = new address[](1);
        usersToRevoke[0] = revokedUser;

        uint256 ownerBalanceBefore = distToken.balanceOf(attacker);
        target.revokeDistributionWallet(usersToRevoke);
        uint256 ownerBalanceAfter = distToken.balanceOf(attacker);

        // Oracle Check: Verify the user's data (and balance) has been deleted.
        (uint balanceAfter, ,,) = target.user(revokedUser);
        assertEq(balanceAfter, 0, "User balance should be 0 after revoke");

        // Sanity check: verify owner received the revoked tokens.
        assertEq(ownerBalanceAfter, ownerBalanceBefore + ALLOCATION_AMOUNT, "Owner did not receive revoked tokens");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

